21	    private static final double LION_CREATION_PROBABILITY    = 0.0125;
22	    private static final double CHEETAH_CREATION_PROBABILITY = 0.0125;
23	    private static final double ZEBRA_CREATION_PROBABILITY   = 0.08;
24	    private static final double GIRAFFE_CREATION_PROBABILITY = 0.08;
25	    private static final double LEMUR_CREATION_PROBABILITY   = 0.081;
26	
27	    // Named indices into the buttons array.
28	    private static final int BTN_PLAY_PAUSE = 0;
29	    private static final int BTN_RUN_LONG   = 1;
30	    private static final int BTN_STEP       = 2;
31	    private static final int BTN_RESET      = 3;
32	    private static final int BTN_QUIT       = 4;
33	
34	    // List of animals in the field.
35	    private List<LivingOrganism> animals;
36	    // List of plants in the field
37	    private List<LivingOrganism> plants;
38	    // The current state of the field.
39	    private Field field;
40	    // A graphical view of the simulation.
41	    private SimulatorView view;
42	    // List of buttons that are used to control the simulation.
43	    private JButton[] buttons;
44	    
45	    /**
46	     * Construct a simulation field with default size.
47	     */
48	    public Simulator()
49	    {
50	        this(DEFAULT_DEPTH, DEFAULT_WIDTH);
51	    }
52	    
53	    /**
54	     * Create a simulation field with the given size.
55	     * @param depth Depth of the field. Must be greater than zero.
56	     * @param width Width of the field. Must be greater than zero.
57	     */
58	    public Simulator(int depth, int width)
59	    {
60	        if(width <= 0 || depth <= 0) {
61	            System.out.println("The dimensions must be greater than zero.");
62	            System.out.println("Using default values.");
63	            depth = DEFAULT_DEPTH;
64	            width = DEFAULT_WIDTH;
65	        }
66	        
67	        animals = new ArrayList<>();
68	        plants = new ArrayList<>();
69	        field = new Field(depth, width);
70	        buttons = new JButton[5];
71	
72	        JButton playPause = new JButton("Play");
73	        playPause.addActionListener(e -> new Thread(() -> playPauseButton()).start());
74	        buttons[BTN_PLAY_PAUSE] = playPause;
75	
76	        JButton runLongSim = new JButton("Run Long Sim");
77	        runLongSim.addActionListener(e -> new Thread(() -> runLongSimulation()).start());
78	        buttons[BTN_RUN_LONG] = runLongSim;
79	
80	        JButton simOneStep = new JButton("Sim One Step");
81	        simOneStep.addActionListener(e -> simulateOneStep());
82	        buttons[BTN_STEP] = simOneStep;
83	
84	        JButton reset = new JButton("Reset");
85	        reset.addActionListener(e -> reset());
86	        buttons[BTN_RESET] = reset;
87	
88	        JButton quit = new JButton("Quit");
89	        quit.addActionListener(e -> quit());
90	        buttons[BTN_QUIT] = quit;
91	        
92	        // Sets the visibility of the buttons in accordance to the current state of the simulation.
93	        buttonToggle();
94	
95	        // Create a view of the state of each location in the field.
96	        view = new SimulatorView(depth, width, buttons);
97	        view.setColor(Zebra.class, Color.BLACK, Color.WHITE);
98	        view.setColor(Giraffe.class, Color.YELLOW, Color.BLACK);
99	        view.setColor(Lemur.class, Color.BLUE, Color.WHITE);
100	        view.setColor(Lion.class, Color.RED, Color.WHITE);
101	        view.setColor(Cheetah.class, Color.ORANGE, Color.BLACK);
102	        view.setColor(Plant.class, Color.GREEN, Color.BLACK);
103	        
104	        // Setup a valid starting point.
105	        reset();
106	    }
107	    
108	    /**
109	     * Controls the functionality of the Play/Pause button. This depends
110	     * on whether the simulation is paused or not.
111	     */
112	    private void playPauseButton() 
113	    {
114	        boolean isPaused = Time.getIsPaused();
115	        
116	        Time.toggleIsPaused();
117	        
118	        if (isPaused) {
119	            if (! Time.getIsFinished()) {
